H.background();
const v = P.v;
const r = 1.0;
const omega = v / r;
const Rpix = 70;
const groundY = 380;
H.line(60, groundY, 840, groundY, { color: H.colors.sub, width: 3 });
const trackW = 700, x0 = 110;
const pxPerM = 60;
const dist = (v * t) * pxPerM;
const cx = x0 + (dist % trackW);
const cy = groundY - Rpix;
const ang = (v * t) / r;
H.circle(cx, cy, Rpix, { stroke: H.colors.accent, width: 3 });
H.circle(cx, cy, 4, { fill: H.colors.ink });
const mx = cx + Rpix * Math.cos(ang), my = cy + Rpix * Math.sin(ang);
H.line(cx, cy, mx, my, { color: H.colors.accent2, width: 3 });
H.circle(mx, my, 6, { fill: H.colors.accent2 });
const conx = cx, cony = cy + Rpix;
H.circle(conx, cony, 7, { fill: H.colors.good });
H.text("contact pt: v=0", conx + 10, cony - 4, { color: H.colors.good, size: 12 });
H.arrow(cx, cy, cx + Math.min(v, 8) * 12, cy, { color: H.colors.violet, width: 3 });
H.text("v", cx + Math.min(v, 8) * 12 + 6, cy - 4, { color: H.colors.violet, size: 13 });
H.arrow(cx, cy - Rpix, cx + Math.min(v, 8) * 24, cy - Rpix, { color: H.colors.yellow, width: 2 });
H.text("top: 2v", cx + 8, cy - Rpix - 10, { color: H.colors.yellow, size: 12 });
H.text("Rolling without slipping: v = omega r", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Contact point is momentarily at rest; top of wheel moves at 2v", 24, 50, { color: H.colors.sub, size: 13 });
H.text("v = " + v.toFixed(1) + " m/s   r = " + r.toFixed(1) + " m   omega = v/r = " + omega.toFixed(2) + " rad/s", 24, 72, { color: H.colors.yellow, size: 13 });
